static const char WEB_JS[] = R"AMEBA_WEB((() => {
  'use strict';
  const el = id => document.getElementById(id);
  const connection = el('connection');
  const diagnostic = el('diagnostic');
  const camera = el('camera');
  const placeholder = el('placeholder');
  const overlay = el('overlay');
  const context = overlay.getContext('2d');
  let busy = false;
  let frameBusy = false;
  let heldObjects = [];
  let lastDetectionAt = 0;
  const RESULT_HOLD_MS = 2000;

  function showResult(name, score) {
    el(name).classList.toggle('active', score !== null);
    el(`${name}Score`).textContent = score === null ? '未偵測' : `${score}%`;
  }

  function drawObjects(data) {
    context.clearRect(0, 0, overlay.width, overlay.height);
    if (!data.ready || data.stale || !Array.isArray(data.objects)) return;
    for (const item of data.objects) {
      const color = item.class === 'cup' ? '#ffb84d' : '#42d49b';
      const name = item.class === 'cup' ? 'Cup 水杯' : 'Bottle 寶特瓶';
      const label = `${name} ${item.score}%`;
      const width = item.x2 - item.x1;
      const height = item.y2 - item.y1;
      if (width <= 0 || height <= 0) continue;
      context.strokeStyle = color;
      context.fillStyle = color;
      context.lineWidth = 3;
      context.strokeRect(item.x1, item.y1, width, height);
      context.font = 'bold 16px system-ui, sans-serif';
      const labelWidth = Math.min(overlay.width - item.x1,
        context.measureText(label).width + 12);
      const labelY = Math.max(0, item.y1 - 25);
      context.fillRect(item.x1, labelY, labelWidth, 25);
      context.fillStyle = '#10251f';
      context.fillText(label, item.x1 + 6, labelY + 18);
    }
  }

  function refreshFrame() {
    if (frameBusy) return;
    frameBusy = true;
    camera.onload = () => {
      placeholder.hidden = true;
      frameBusy = false;
    };
    camera.onerror = () => {
      placeholder.hidden = false;
      placeholder.textContent = '即時影像暫時無法取得，正在重試…';
      frameBusy = false;
    };
    camera.src = `/snapshot?t=${Date.now()}`;
  }

  async function refresh() {
    if (busy) return;
    busy = true;
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 1800);
    try {
      const response = await fetch(`/api/status?t=${Date.now()}`, {
        cache: 'no-store', signal: controller.signal
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const data = await response.json();
      const best = {cup: null, bottle: null};
      if (data.ready && !data.stale && Array.isArray(data.objects) && data.objects.length) {
        heldObjects = data.objects;
        lastDetectionAt = Date.now();
      } else if (Date.now() - lastDetectionAt >= RESULT_HOLD_MS) {
        heldObjects = [];
      }
      const displayed = {...data, objects: heldObjects, stale: false};
      if (displayed.ready && Array.isArray(displayed.objects)) {
        for (const item of displayed.objects) {
          if (item.class in best) best[item.class] = Math.max(best[item.class] || 0, item.score);
        }
      }
      showResult('cup', best.cup);
      showResult('bottle', best.bottle);
      drawObjects(displayed);
      connection.className = 'status live';
      connection.textContent = '已連線';
      diagnostic.textContent = data.ready
        ? `AI 以 5 FPS 持續辨識｜結果保留 2 秒｜顯示 ${heldObjects.length} 個物件`
        : 'Ameba 已連線，AI 模型正在啟動…';
    } catch (error) {
      showResult('cup', null); showResult('bottle', null);
      context.clearRect(0, 0, overlay.width, overlay.height);
      connection.className = 'status error';
      connection.textContent = '連線失敗';
      diagnostic.textContent = error.name === 'AbortError' ? 'Ameba 回應逾時' : `連線錯誤：${error.message}`;
    } finally {
      clearTimeout(timer); busy = false;
    }
  }

  refresh();
  refreshFrame();
  setInterval(refresh, 500);
  setInterval(refreshFrame, 300);
})();
)AMEBA_WEB";
